const JSON_SEQUENCE_MEDIA_TYPES: [&str; 6] = [
    "application/x-ndjson",
    "application/ndjson",
    "application/jsonl",
    "application/json-lines",
    "application/x-jsonlines",
    "application/json-seq",
];

/// One NDJSON line's record text: without surrounding whitespace, nor the RS a
/// JSON text sequence record starts with.
fn json_record_text(line: &str) -> &str {
    line.trim().trim_start_matches('\u{1e}')
}

/// Writes a structured body under its declared media type: a form body as its
/// fields' `name=value` pairs, an array field repeating its name; a JSON
/// sequence type as one record per line, each also starting with RS under a
/// JSON text sequence; every other type as JSON. XML and vendor types have no
/// encoder of their own and are written as JSON, as the response side reads them.
fn encode_structured_body(content_type: &str, body: &serde_json::Value) -> Vec<u8> {
    let media_type = content_type.split(';').next().unwrap_or_default().trim();
    if JSON_SEQUENCE_MEDIA_TYPES
        .iter()
        .any(|sequence| media_type.eq_ignore_ascii_case(sequence))
    {
        let separator = if media_type.eq_ignore_ascii_case("application/json-seq") {
            "\u{1e}"
        } else {
            ""
        };
        let records: Vec<&serde_json::Value> = match body {
            serde_json::Value::Array(items) => items.iter().collect(),
            other => vec![other],
        };
        return records
            .iter()
            .map(|record| format!("{}{}\n", separator, record))
            .collect::<String>()
            .into_bytes();
    }
    match body {
        serde_json::Value::Object(fields)
            if media_type.eq_ignore_ascii_case("application/x-www-form-urlencoded") =>
        {
            let pairs: Vec<(String, String)> = fields
                .iter()
                .flat_map(|(name, value)| match value {
                    serde_json::Value::Array(items) => items
                        .iter()
                        .map(|item| (name.clone(), query_value(item)))
                        .collect(),
                    serde_json::Value::Null => Vec::new(),
                    other => vec![(name.clone(), query_value(other))],
                })
                .collect();
            encode_pairs(&pairs).into_bytes()
        }
        other => serde_json::to_vec(other).expect("a JSON value always serializes"),
    }
}

/// The query encoding every SDK in the family shares: RFC 3986 unreserved plus
/// the sub-delimiters a URI component may carry literally. A space becomes
/// `%20` rather than `+`, because `+` is a literal plus in a URI query and only
/// means a space to a parser reading the component as an HTML form body.
fn encode_query_component(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.as_bytes() {
        match byte {
            b'A'..=b'Z'
            | b'a'..=b'z'
            | b'0'..=b'9'
            | b'-'
            | b'_'
            | b'.'
            | b'~'
            | b'!'
            | b'*'
            | b'\''
            | b'('
            | b')' => out.push(*byte as char),
            other => out.push_str(&format!("%{other:02X}")),
        }
    }
    out
}

